//! Compiles contributor credits into the binary (craftrules standards/contributors.md):
//! usernames from `contributors/contributors.json` (generated by craftrules' contributors.py).
//! A missing or malformed file still builds, with no contributors listed.
use std::fmt::Write as _;
use std::path::PathBuf;

fn main() {
    let root = PathBuf::from(std::env::var_os("CARGO_MANIFEST_DIR").unwrap_or_default()).join("../../contributors");
    let json = root.join("contributors.json");
    println!("cargo::rerun-if-changed={}", json.display());
    println!("cargo::rerun-if-changed={}", root.join("people.toml").display());
    let mut out = String::from("pub static CONTRIBUTORS: &[&str] = &[");
    match std::fs::read_to_string(&json) {
        Ok(text) => match serde_json::from_str::<serde_json::Value>(&text) {
            Ok(v) => {
                if let Some(list) = v.get("contributors").and_then(|c| c.as_array()) {
                    for c in list {
                        if let Some(login) = c.get("login").and_then(|l| l.as_str()) {
                            let _ = write!(out, "{login:?}, ");
                        }
                    }
                }
            }
            Err(e) => println!("cargo::warning=contributors.json: {e}"),
        },
        Err(_) => println!("cargo::warning=no contributors/contributors.json (run craftrules scripts/contributors.py)"),
    }
    out.push_str("];\n");
    let dest = PathBuf::from(std::env::var_os("OUT_DIR").unwrap_or_default()).join("credits.rs");
    if let Err(e) = std::fs::write(&dest, out) {
        println!("cargo::error=writing {}: {e}", dest.display());
    }
}
